package com.yeyamo_mobile.api.mission_reward_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.mission_reward_service.domain.AdminDefinitionStatus;import jakarta.persistence.*;
@Entity@Table(name="xp_rules")public class XpRuleEntity{
 @Id private UUID id;@Column(nullable=false,unique=true,length=120)private String action;@Column(name="xp_amount",nullable=false)private int xpAmount;@Column(name="frequency_limit")private Integer frequencyLimit;@Column(name="daily_limit")private Integer dailyLimit;@Column(name="conditions_json",nullable=false,columnDefinition="TEXT")private String conditions;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AdminDefinitionStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;
 public static XpRuleEntity create(String action,int amount,Integer frequency,Integer daily,String conditions){XpRuleEntity e=new XpRuleEntity();e.id=UUID.randomUUID();e.action=required(action);e.apply(amount,frequency,daily,conditions);e.status=AdminDefinitionStatus.DRAFT;e.createdAt=Instant.now();e.updatedAt=e.createdAt;return e;}public void update(int amount,Integer frequency,Integer daily,String conditions){apply(amount,frequency,daily,conditions);updatedAt=Instant.now();}private void apply(int amount,Integer frequency,Integer daily,String conditions){if(amount<=0||frequency!=null&&frequency<=0||daily!=null&&daily<=0)throw new IllegalArgumentException("XP values must be positive");xpAmount=amount;frequencyLimit=frequency;dailyLimit=daily;this.conditions=required(conditions);}public void status(AdminDefinitionStatus value){status=Objects.requireNonNull(value);updatedAt=Instant.now();}private static String required(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("Required value");return value.trim();}
 public UUID getId(){return id;}public String getAction(){return action;}public int getXpAmount(){return xpAmount;}public Integer getFrequencyLimit(){return frequencyLimit;}public Integer getDailyLimit(){return dailyLimit;}public String getConditions(){return conditions;}public AdminDefinitionStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}
}
